# runs.py RUN_DIR [PATTERN]: Bash calls that build, run a suite or a stage, per agent, with time
import json, sys, os, re, glob, datetime
d=sys.argv[1]; pat=re.compile(sys.argv[2] if len(sys.argv)>2 else r'ant (compileAll|clean|testSystem|testQuick|testFast|testOnly|testSpecData|tex|genSource)|checker-count|distance/run|count-run|CompilerLibrary|gate-functions|run_gate|microgpt|MicroGpt.*Quick|demos|ladder')
def lab(f):
    try: return json.load(open(f[:-6]+'.meta.json'))['description']
    except Exception: return '?'
for f in sorted(glob.glob(os.path.join(d,'agent-*.jsonl'))):
    L=lab(f); out=[]
    for line in open(f,errors='replace'):
        try: r=json.loads(line)
        except Exception: continue
        m=r.get('message')
        if not isinstance(m,dict) or m.get('role')!='assistant': continue
        for c in m.get('content') or []:
            if isinstance(c,dict) and c.get('type')=='tool_use' and c.get('name')=='Bash':
                cmd=c['input'].get('command','')
                if pat.search(cmd):
                    t=r.get('timestamp','')[11:19]
                    out.append((t, ' '.join(cmd.split())[:260]))
    if out:
        print('##',L)
        seen=set()
        for t,c in out:
            if (t,c) in seen: continue
            seen.add((t,c)); print(' ',t,c)
