#!/usr/bin/env python3
# spans28.py: tokens written in three spans, spend.py's method (input + cache creation, one count per message id),
# over the live folders and, for transcripts only the backup holds, the backup's copies; a transcript counts in
# the span where it last changed: its mtime for a live file, its last record's timestamp for a backup-only file
# (a backup copy's mtime is its checkout's). The coordinating session's own transcript (fe616d40*) is left out, as spend.py does.
import json, os, glob, sys
from datetime import datetime
LIVE='/root/.claude/projects/-home-user-fortress'
BACK='/home/user/fortress-transcripts-blinded/projects/-home-user-fortress'
S='fe616d40-a9c6-56d7-9da1-7168a172765d'
def files(root):
    fs=glob.glob(f'{root}/*.jsonl')+glob.glob(f'{root}/{S}/subagents/*.jsonl')+glob.glob(f'{root}/{S}/subagents/workflows/*/agent-*.jsonl')
    return [f for f in fs if not os.path.basename(f).startswith('fe616d40')]
def ts(s):
    try: return datetime.fromisoformat(s.replace('Z','+00:00')).timestamp()
    except Exception: return None
def measure(f):
    seen={}; last=None
    for line in open(f, errors='replace'):
        try: r=json.loads(line)
        except Exception: continue
        t=r.get('timestamp'); t=ts(t) if isinstance(t,str) else None
        if t: last=t if last is None else max(last,t)
        m=r.get('message') if isinstance(r.get('message'),dict) else None
        if not m or 'usage' not in m: continue
        seen[m.get('id') or id(m)]=m['usage']
    w=sum(u.get('input_tokens',0)+u.get('cache_creation_input_tokens',0) for u in seen.values())
    return w, len(seen), last
live={os.path.relpath(f,LIVE):f for f in files(LIVE)}
back={os.path.relpath(f,BACK):f for f in files(BACK)}
rows=[]
for rel,f in live.items():
    w,n,last=measure(f); rows.append((rel,'live',os.path.getmtime(f),last,w,n))
for rel,f in back.items():
    if rel in live: continue
    w,n,last=measure(f)
    if last is None: continue
    rows.append((rel,'backup',last,last,w,n))
import pickle; pickle.dump(rows, open(os.path.join(os.path.dirname(__file__),'spanrows.pkl'),'wb'))
print(len(rows),'transcripts with records;', sum(1 for r in rows if r[1]=='live'),'live,', sum(1 for r in rows if r[1]=='backup'),'backup only')

